const sales = $('Supabase: Fetch Today Sales').item.json;
const reports = $('Supabase: Fetch Staff Reports').all().map(i => i.json);
const credits = $('Supabase: Fetch Credit Alerts').all().map(i => i.json);

const totalSales = sales.total_sales || 0;
const target = 30000;
const gap = target - totalSales;
const hour = new Date().getHours();

// Only alert if worth alerting
const alerts = [];

// Low sales alerts (only during business hours)
if (hour >= 9 && hour <= 21) {
  if (totalSales < 10000 && hour >= 14) {
    alerts.push({ type: 'low_sales_critical', sales: totalSales, gap });
  } else if (totalSales < 15000 && hour >= 18) {
    alerts.push({ type: 'low_sales_warning', sales: totalSales, gap });
  }
}

// Missing reports (9pm check)
if (hour === 21) {
  const missing = reports.filter(r => !r.submitted).map(r => r.staff_name);
  if (missing.length > 0) {
    alerts.push({ type: 'missing_reports', staff: missing });
  }
}

// Credit over limit (check at 9am and 3pm)
if (hour === 9 || hour === 15) {
  if (credits.length > 0) {
    alerts.push({ type: 'credit_over_limit', accounts: credits });
  }
}

// Full 9pm summary (always)
if (hour === 21) {
  alerts.push({ 
    type: 'daily_summary',
    sales: totalSales,
    target,
    gap,
    achieved: totalSales >= target
  });
}

return [{ json: { alerts, sales: totalSales, target, gap, hour, reports, credits } }];

const { alerts, sales, target, gap, credits } = $input.item.json;
const lines = [];

for (const a of alerts) {
  if (a.type === 'daily_summary') {
    lines.push(a.achieved
      ? `✅ Daily summary: NPR ${sales.toLocaleString()} — target hit! 🎉`
      : `📊 Daily summary: NPR ${sales.toLocaleString()} / ${target.toLocaleString()} — NPR ${gap.toLocaleString()} short`);
  }
  if (a.type === 'low_sales_critical') {
    lines.push(`🔴 LOW SALES ALERT: Only NPR ${a.sales.toLocaleString()} by now — NPR ${a.gap.toLocaleString()} behind target. Accelerate!`);
  }
  if (a.type === 'low_sales_warning') {
    lines.push(`🟡 Sales check: NPR ${a.sales.toLocaleString()} so far — NPR ${a.gap.toLocaleString()} still needed before close.`);
  }
  if (a.type === 'missing_reports') {
    lines.push(`⚠️ Missing daily reports from: ${a.staff.join(', ')} — remind them to submit.`);
  }
  if (a.type === 'credit_over_limit') {
    const list = a.accounts.map(c => `${c.account_name}: NPR ${c.balance}`).join(', ');
    lines.push(`💳 Credit over NPR 3,000: ${list}`);
  }
}

return [{ json: { message: '🍴 Baadar Canteen Alert\n\n' + lines.join('\n') } }];
